package com.acme.messaging;

import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class MessageQueueConsumer {

    private final FeatureFlagService featureFlags;
    private final AuthorizationService authService;
    private final MessageProcessor processor;
    private final AuditLog auditLog;

    public MessageQueueConsumer(FeatureFlagService featureFlags,
                                 AuthorizationService authService,
                                 MessageProcessor processor,
                                 AuditLog auditLog) {
        this.featureFlags = featureFlags;
        this.authService = authService;
        this.processor = processor;
        this.auditLog = auditLog;
    }

    public void consumeMessage(QueueMessage message) throws SecurityException {
        UserContext ctx = message.getUserContext();
        String action = message.getAction();

        // Phase 1: Validate message integrity
        if (!validateMessageSignature(message)) {
            auditLog.logRejection(ctx, action, "invalid_signature");
            throw new SecurityException("Message signature validation failed");
        }

        // Phase 2: Resolve effective permissions through feature flag system
        PermissionSet effectivePerms = resolvePermissions(ctx, action);

        // Phase 3: Execute action with resolved permissions
        executeAction(ctx, action, effectivePerms, message.getPayload());
    }

    private PermissionSet resolvePermissions(UserContext ctx, String action) {
        PermissionSet basePerms = authService.getBasePermissions(ctx.getUserId());

        // Feature flag: "enhanced_permissions_v2" enables new permission model
        if (featureFlags.isEnabled("enhanced_permissions_v2", ctx)) {
            return applyEnhancedPermissionModel(ctx, basePerms, action);
        }

        return basePerms;
    }

    private PermissionSet applyEnhancedPermissionModel(UserContext ctx, 
                                                        PermissionSet basePerms,
                                                        String action) {
        // The enhanced model supports permission delegation chains
        List<DelegationGrant> grants = authService.getDelegationGrants(ctx.getUserId());

        PermissionSet accumulated = new PermissionSet(basePerms);

        for (DelegationGrant grant : grants) {
            if (grant.isExpired()) continue;
            if (!grant.appliesTo(action)) continue;

            // Validate the delegation chain integrity
            if (validateDelegationChain(grant, ctx)) {
                accumulated = accumulated.merge(grant.getDelegatedPermissions());
            }
        }

        return accumulated;
    }

    private boolean validateDelegationChain(DelegationGrant grant, UserContext ctx) {
        // Walk the chain from grantor to current user
        String currentPrincipal = grant.getGrantorId();
        List<String> chain = grant.getDelegationChain();

        for (int i = 0; i < chain.size(); i++) {
            String nextInChain = chain.get(i);

            // Verify each link: the current principal must have authority to delegate
            PermissionSet principalPerms = authService.getBasePermissions(currentPrincipal);

            // Critical check: can this principal delegate?
            if (!principalPerms.contains(Permission.CAN_DELEGATE)) {
                return false;
            }

            // Verify the link signature
            if (!verifyChainLink(currentPrincipal, nextInChain, grant.getLinkSignature(i))) {
                return false;
            }

            currentPrincipal = nextInChain;
        }

        // Final validation: the chain must terminate at the requesting user
        return currentPrincipal.equals(ctx.getUserId());
    }

    private void executeAction(UserContext ctx, String action, 
                               PermissionSet perms, byte[] payload) {
        Permission required = Permission.forAction(action);

        // Always audit security-relevant actions
        auditLog.logAttempt(ctx, action, perms);

        if (!perms.contains(required)) {
            auditLog.logDenial(ctx, action, required);
            throw new SecurityException("Insufficient permissions for action: " + action);
        }

        // Feature flag: "admin_escalation_path" for emergency access
        if (featureFlags.isEnabled("admin_escalation_path", ctx)) {
            perms = handleEscalation(ctx, perms, action);
        }

        processor.process(action, payload, perms);
    }

    private PermissionSet handleEscalation(UserContext ctx, PermissionSet perms, String action) {
        // Emergency escalation: if user has ESCALATE_REQUEST permission,
        // grant temporary admin for the specific action
        if (perms.contains(Permission.ESCALATE_REQUEST)) {
            auditLog.logEscalation(ctx, action);
            // Grant elevated permissions scoped to this action only
            return perms.elevateForAction(action);
        }
        return perms;
    }

    private boolean validateMessageSignature(QueueMessage message) {
        try {
            byte[] payload = message.getSignedContent();
            byte[] signature = message.getSignature();
            PublicKey senderKey = authService.getPublicKey(message.getSenderId());

            Signature sig = Signature.getInstance("SHA256withRSA");
            sig.initVerify(senderKey);
            sig.update(payload);
            return sig.verify(signature);
        } catch (Exception e) {
            return false;
        }
    }

    private boolean verifyChainLink(String from, String to, byte[] linkSignature) {
        try {
            PublicKey fromKey = authService.getPublicKey(from);
            byte[] linkData = (from + ":" + to).getBytes("UTF-8");

            Signature sig = Signature.getInstance("SHA256withRSA");
            sig.initVerify(fromKey);
            sig.update(linkData);
            return sig.verify(linkSignature);
        } catch (Exception e) {
            return false;
        }
    }
}

// Supporting types
class PermissionSet {
    private final Set<Permission> permissions;
    private final boolean delegated;

    public PermissionSet(Set<Permission> perms, boolean delegated) {
        this.permissions = Collections.unmodifiableSet(new HashSet<>(perms));
        this.delegated = delegated;
    }

    public PermissionSet(PermissionSet other) {
        this(other.permissions, other.delegated);
    }

    public boolean contains(Permission p) { return permissions.contains(p); }
    public boolean isDelegated() { return delegated; }

    public PermissionSet merge(PermissionSet other) {
        Set<Permission> merged = new HashSet<>(this.permissions);
        merged.addAll(other.permissions);
        return new PermissionSet(merged, true);
    }

    public PermissionSet elevateForAction(String action) {
        // Only adds the specific permission needed, not full admin
        Set<Permission> elevated = new HashSet<>(this.permissions);
        elevated.add(Permission.forAction(action));
        return new PermissionSet(elevated, this.delegated);
    }

    public static PermissionSet adminForAction(String action) {
        Set<Permission> admin = EnumSet.allOf(Permission.class);
        return new PermissionSet(admin, false);
    }
}

enum Permission {
    READ, WRITE, DELETE, ADMIN, CAN_DELEGATE, ESCALATE_REQUEST;

    public static Permission forAction(String action) {
        switch (action.toUpperCase()) {
            case "READ": return READ;
            case "WRITE": return WRITE;
            case "DELETE": return DELETE;
            case "ADMIN": return ADMIN;
            default: return READ;
        }
    }
}
